/**
 * The Google Fonts library, browsed straight off the Fontsource CDN.
 *
 * Nothing is downloaded until a font is actually previewed or selected, and no font
 * binary is ever bundled — only the small index at `/fonts/google-fonts.json`.
 * The index itself is generated by `scripts/fontsIndex.ts` (see `bun run fonts:index`).
 */

export type FontCategory = 'handwriting' | 'display' | 'serif' | 'sans-serif' | 'monospace'

export interface GoogleFont {
  /** Fontsource family id, e.g. "inter" */
  id: string
  /** Human family name, e.g. "Inter" */
  name: string
  /** css subset slug of the family's default script, e.g. "latin" */
  subset: string
  /** the static weight the index picked (closest to 400) */
  weight: number
  category: string
}

type Row = [id: string, name: string, subset: string, weight: number, category: string]

type Index = {
  generated: string
  source: string
  licenses: string[]
  fonts: Row[]
}

export const FONT_CATEGORIES = [
  'handwriting',
  'display',
  'serif',
  'sans-serif',
  'monospace',
] as const

export function googleFontUrl(id: string, subset: string, weight: number): string {
  return `https://cdn.jsdelivr.net/npm/@fontsource/${id}/files/${id}-${subset}-${weight}-normal.woff2`
}

let cache: Promise<GoogleFont[]> | null = null

/** Fetched once per session. */
export function loadGoogleFonts(): Promise<GoogleFont[]> {
  cache ??= fetch('/fonts/google-fonts.json')
    .then((r) => {
      if (!r.ok) throw new Error(`font index: HTTP ${r.status}`)
      return r.json() as Promise<Index>
    })
    .then((idx) =>
      idx.fonts.map(([id, name, subset, weight, category]): GoogleFont => ({
        id,
        name,
        subset,
        weight,
        category,
      })),
    )
    .catch((e) => {
      cache = null // let a later open retry rather than caching the failure
      throw e
    })

  return cache
}

/** css fallback stack per category, appended after the picked face. */
export const CATEGORY_FALLBACK: Record<string, string> = {
  'sans-serif': 'sans-serif',
  serif: 'serif',
  monospace: 'ui-monospace, monospace',
  display: 'serif',
  handwriting: 'cursive',
}

/** Family name from a saved fontFamily stack, e.g. '"Inter", sans-serif' -> Inter. */
export function familyNameOf(stack: string): string {
  return stack.replace(/["']/g, '').split(',')[0]?.trim() ?? stack
}

/** Save a picked google family as a quoted stack with its category fallback. */
export function googleFontStack(f: GoogleFont): string {
  return `"${f.name}", ${CATEGORY_FALLBACK[f.category] ?? 'sans-serif'}`
}
